/* === Mobile First: viết CSS cho mobile trước === */
.responsive-demo {
  display: flex;
  flex-direction: column; /* Mobile: xếp dọc */
  gap: 8px;
}

.r-col {
  background: #00b894;
  color: white;
  padding: 16px;
  text-align: center;
  border-radius: 6px;
  font-weight: bold;
}

/* Tablet trở lên (≥ 500px): xếp ngang */
@media (min-width: 500px) {
  .responsive-demo {
    flex-direction: row;
  }
  .r-col {
    flex: 1;
    background: #0984e3;
  }
}

.breakpoint-info {
  font-size: 11px;
  color: #999;
  margin-top: 8px;
  text-align: center;
}

.media-card {
  padding: 20px;
  border-radius: 10px;
  font-weight: bold;
  text-align: center;
  background: #6c5ce7;
  color: white;
}

/* Chỉ áp dụng cho màn hình từ 400px-800px */
@media (min-width: 400px) and (max-width: 800px) {
  .media-card {
    background: #00b894;
  }
}

/* Khi người dùng bật Dark Mode trên hệ thống */
@media (prefers-color-scheme: dark) {
  .media-card {
    background: #2d3436;
    border: 1px solid #636e72;
  }
}

/* Tắt animation cho người bị say sóng hình */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

/* BƯỚC 1: Mobile mặc định — 1 cột đơn giản */
.mf-grid {
  display: grid;
  grid-template-columns: 1fr; /* 1 cột */
  gap: 10px;
}

.mf-card {
  background: #6c5ce7;
  color: white;
  padding: 18px;
  border-radius: 10px;
  text-align: center;
  font-weight: bold;
}

/* BƯỚC 2: Tablet (≥ 500px) — 2 cột */
@media (min-width: 500px) {
  .mf-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Lưu ý: Code ở đây chỉ THÊM (2 cột), không ghi đè padding/color — tiết kiệm! */

.img-compare {
  display: flex;
  gap: 16px;
}

.img-box {
  text-align: center;
  font-size: 12px;
  color: #666;
}

.img-placeholder {
  width: 120px;
  height: 90px;
  border: 2px solid #6c5ce7;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  color: white;
  font-size: 11px;
}

/* cover: lấp đầy, có thể cắt */
.cover {
  background: linear-gradient(45deg, #6c5ce7 30%, #a29bfe 70%);
}

/* contain: hiện hết, có thể thừa chỗ */
.contain {
  background: linear-gradient(45deg, #00b894 30%, #55efc4 70%);
  background-size: 80% 60%;
  background-repeat: no-repeat;
  background-position: center;
}

.fluid-h1 {
  /* clamp(tối_thiểu, lý_tưởng, tối_đa) */
  font-size: clamp(1.3rem, 4vw, 2.5rem);
  color: #d63031;
  margin-bottom: 8px;
  line-height: 1.2;
}

.fluid-p {
  font-size: clamp(0.85rem, 1.8vw, 1.1rem);
  color: #555;
  line-height: 1.6;
}

.hero-section {
  /* 100vh = full chiều cao viewport */
  height: 50vh; /* Dùng 50vh trong demo cho dễ xem */
  min-height: 200px;
  background: linear-gradient(135deg, #2d3436, #636e72);
  color: white;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  text-align: center;
}

.hero-title {
  font-size: clamp(1.5rem, 5vw, 3rem); /* Font theo vw */
  margin-bottom: 8px;
}

/* Bước 1: Khai báo container */
.container-demo {
  container-type: inline-size;
  container-name: card-container;
  max-width: 400px;
  border: 2px dashed #6c5ce7;
  border-radius: 10px;
  padding: 12px;
}

/* Style mặc định (nhỏ): xếp dọc */
.cq-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 8px;
}

.cq-icon {
  font-size: 2rem;
}

.cq-info h4 { margin: 0; color: #2d3436; }
.cq-info p { margin: 0; font-size: 12px; color: #999; }

/* Bước 2: Khi container ≥ 300px → xếp ngang */
@container card-container (min-width: 300px) {
  .cq-card {
    flex-direction: row;
    text-align: left;
  }
}

/* Cách 1: CSS Grid (khuyến nghị) */
.resp-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 10px;
}

.resp-card {
  background: linear-gradient(135deg, #a29bfe, #6c5ce7);
  color: white;
  padding: 18px;
  border-radius: 10px;
  text-align: center;
  font-weight: bold;
}

